/* V11: conversation, reviewable changes and contextual handoff. */
(()=>{
const UI=EvalUI,C=EvaluationCore,M=CollaborationModel;
const core=()=>UI.core,db=()=>core().db,now=()=>new Date().toISOString();
const b=(label,act,key='',cls='')=>`<button type="button" class="btn ${cls}" data-cm="${act}" data-key="${esc(key)}">${label}</button>`;
const vb=(label,act,key='',cls='')=>`<button type="button" class="btn ${cls}" data-v2="${act}" data-key="${esc(key)}">${label}</button>`;
const tm=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' UTC+08:00':'此前';
const task=w=>w.plazaTaskId?PlazaCore.task(PlazaReview.state(),w.plazaTaskId):S.evalTasks.find(t=>t.id===w.taskId),asset=w=>core().find(w.assetKey),work=()=>db().works.find(w=>w.id===S.activeWork)||db().works[0];
const rounds=w=>db().rounds.filter(r=>r.workId===w.id),pending=w=>db().instructions.filter(i=>i.workId===w.id&&i.state==='待执行');
const ui=w=>w.ui||(w.ui={mode:'discuss',tab:'diff',draft:''});
const running=w=>rounds(w).find(r=>r.state==='运行中');
const text=s=>esc(s||'').replace(/\n/g,'<br>');
function show(){const field=document.getElementById('cm-draft'),focused=field&&document.activeElement===field,start=field?.selectionStart,end=field?.selectionEnd,thread=document.querySelector('.cm-thread'),nearBottom=thread&&(thread.scrollHeight-thread.scrollTop-thread.clientHeight<60),scroll=thread?.scrollTop;UI.render();const next=document.querySelector('.cm-thread');if(next)next.scrollTop=nearBottom?next.scrollHeight:scroll||0;if(focused){const n=document.getElementById('cm-draft');n?.focus({preventScroll:true});n?.setSelectionRange(start,end);}}
function open(w){S.activeWork=w.id;go('work');}
function addMessage(w,message,actor=roleNames[S.role]){(w.messages||(w.messages=[])).push({id:core().id('MSG'),actor,text:message,at:now()});}
function migrate(){
 for(const old of S.newWorks||[]){if(!old.id?.startsWith('CAP-')||db().works.some(w=>w.legacyId===old.id))continue;const a=core().adopt({id:old.id,version:'r1',kind:'executor',type:'执行器',name:old.goal.replace(/ · 契约与资格准备$/,''),source:'能力登记',targets:[],assetSpec:{fields:{}},config:{capabilityRegistration:true,supportedTask:'待补充'}});db().works.push({id:core().id('CW'),legacyId:old.id,title:old.goal,status:'进行中',assetKey:C.key(a),messages:[]});}
 for(const r of db().rounds)if(r.state==='运行中')M.stop(db(),r,'已中断');
 const w=db().works.find(w=>w.id==='CW-028');if(w&&!w.v11Initialized){w.v11Initialized=true;if(!rounds(w).length){const a=asset(w);addMessage(w,'请帮我检查这个用例：用户拒绝后，哪些行为要禁止，哪些证据必须留下？','林工');db().rounds.push({id:core().id('AI'),workId:w.id,state:'已完成',assetKey:w.assetKey,instructions:[],patches:M.suggest(a,task(w)),demo:true,seed:true,startedAt:now(),finishedAt:now()});}}
 UI.commit();
}
function members(){return '<div class="cm-members"><span title="工程师">林</span><span class="expert" title="领域专家">陈</span><span class="quality" title="质量审核">周</span><small>评测 · 业务 · 按需专项复核</small></div>';}
function workCard(w){const a=asset(w),r=rounds(w).at(-1),count=r?.patches?.filter(p=>p.state==='待审查').length||0;return `<button class="cm-work-card" data-cm="open" data-key="${esc(w.id)}"><div class="cm-between"><span class="cm-kicker">${esc(w.id)}</span>${stateBadge(w.status)}</div><h3>${esc(w.title)}</h3><p>${a?esc(a.name+' · '+a.version):esc(task(w)?.name||'评测方案协作')}</p><div class="cm-between"><span class="cm-preview">${count?count+' 处建议等待你审查':a?.status==='待准入'?'等待 '+esc(a.governance.assigneeName||roleNames[a.governance.assignee]):'继续讨论与完善成果'}</span><span class="cm-arrow">↗</span></div></button>`;}
pages.collab=()=>head('人机协作','把想法说清楚，和 AI 一起形成可以审查、继续完善的成果。',b('发起协作','new-work','','primary'))+`<div class="cm-start-grid"><div class="cm-start"><span class="cm-kicker">围绕正在做的事</span><h2>从任务或资产开始一段协作</h2><p>保留讨论上下文，逐项审查建议，再把确定的内容交给下一位同事。</p><div>${b('选择任务','new-work','task')}${b('选择资产','new-work','asset')}</div></div><div class="cm-start cm-guide"><span class="cm-spark">✦</span><h3>你决定改什么，AI 帮你整理</h3><p>讨论先留在对话里；工作指令加入下一轮。每一处建议都能对照原文，单独采纳或保留。</p><span class="cm-demo">演示助手 · 合成建议</span></div></div><div class="cm-section-head"><h2>继续协作</h2><span>${db().works.filter(w=>w.status==='进行中').length} 个进行中的事项</span></div><div class="cm-work-grid">${db().works.map(workCard).join('')}</div>`;
function roundBubble(w,r){const count=r.patches?.length||0,stages=['读取关联内容与本轮指令','对照现有规则整理建议','准备可以逐项审查的差异'];return `<article class="cm-message cm-ai"><div class="cm-avatar">✦</div><div class="cm-message-body"><div class="cm-message-meta"><b>协作助手</b><span class="cm-demo">${r.seed?'合成示例':'演示助手'}</span><time>${tm(r.finishedAt||r.startedAt)}</time></div><div class="cm-bubble">${r.state==='运行中'?`<div class="cm-progress" role="status"><i></i>${stages[r.stage||0]}</div><p>本轮只读取启动时的关联版本；你可以继续讨论或给下一轮加指令。</p>${b('停止本轮','stop',r.id,'sm')}`:r.state==='已完成'?`${r.output?'<p>'+text(r.output)+'</p>':''}<p>${count?`我整理了 <strong>${count} 处可审查的建议</strong>。${r.patches.map(p=>esc(p.title)).join('；')}。`:'这轮没有新的字段差异。可以补充具体约束，或直接打开成果继续编辑。'}</p><p class="cm-muted">${r.seed?'这是用于体验逐项审查的合成建议。':'已按当前输入生成合成建议，未调用真实模型。'}采纳前请核对业务含义。</p>${count?b('查看本轮差异','round-view',r.id,'sm'):''}`:`<p>${r.state==='已中断'?'页面中断，本轮没有形成成果。':'本轮已停止，没有修改成果。'}已读取的指令已放回待执行队列。</p>${b('重新启动一轮','start',w.id,'sm')}`}<details class="cm-inputs"><summary>本轮上下文 · ${esc(r.assetKey||r.taskId||'未关联')} · ${r.instructions?.length||0} 条指令</summary>${r.instructions?.length?'<ul>'+r.instructions.map(x=>'<li>'+text(x)+'</li>').join('')+'</ul>':'<p>没有新增指令，依据关联对象整理。</p>'}</details></div></div></article>`;}
function conversation(w){const events=[...(w.messages||[]).map(m=>({at:m.at,html:`<article class="cm-message"><div class="cm-avatar human">${esc((m.actor||'我').slice(0,1))}</div><div class="cm-message-body"><div class="cm-message-meta"><b>${esc(m.actor)}</b><time>${tm(m.at)}</time></div><div class="cm-bubble">${text(m.text)}</div></div></article>`})),...rounds(w).map(r=>({at:r.startedAt,html:roundBubble(w,r)}))].sort((a,b)=>(a.at||'').localeCompare(b.at||''));return events.map(x=>x.html).join('')||'<div class="cm-empty-chat"><span>✦</span><h3>想先一起解决什么？</h3><p>可以讨论目标、审查已有内容，或给下一轮一条具体指令。</p></div>';}
function composer(w){const s=ui(w),closed=w.status==='已关闭',run=running(w),list=pending(w);return `<div class="cm-composer"><div class="cm-mode" role="group" aria-label="消息类型">${b('讨论','mode','discuss',s.mode==='discuss'?'active':'')}${b('给 AI 工作指令','mode','instruction',s.mode==='instruction'?'active':'')}</div><label class="sr-only" for="cm-draft">${s.mode==='instruction'?'下一轮工作指令':'讨论内容'}</label><textarea id="cm-draft" rows="3" placeholder="${closed?'事项已关闭，重新打开后可继续':s.mode==='instruction'?'例如：请补充超时分支，并说明需要保留哪些证据。':'说说你的判断，或告诉协作伙伴哪里还需要调整…'}" ${closed?'disabled':''}>${esc(s.draft||'')}</textarea><div class="cm-compose-footer"><span>${s.mode==='instruction'?'下一轮启动时读取，可在启动前撤回':'记录讨论，不自动触发 AI 轮次'} · ⌘ / Ctrl + Enter</span>${b(s.mode==='instruction'?'加入下一轮':'发送讨论','send',w.id,'primary')}</div></div><div class="cm-queue"><div class="cm-between"><h3>下一轮工作指令 <span>${list.length}</span></h3><span class="cm-muted">${run?'本轮已锁定输入，新指令留给下一轮':'待执行，可撤回'}</span></div>${list.map(i=>`<div class="cm-queued"><span>${text(i.text)}</span>${b('撤回','withdraw',i.id,'ghost sm')}</div>`).join('')||'<p class="cm-muted">还没有新指令。也可以直接依据当前成果启动一轮。</p>'}<div class="cm-round-start"><div><b>${run?'AI 正在整理本轮建议':'准备好后，启动下一轮'}</b><small>预估 1 演示单位 · ${list.length} 条指令 · ${esc(asset(w)?.version||'当前任务')}</small></div>${run?b('停止本轮','stop',run.id):closed?'<button class="btn" disabled title="事项已关闭，请先重新打开">启动 AI 轮次</button>':b('✦ 启动 AI 轮次','start',w.id,'primary')}</div></div>`;}
function selectedRound(w){return rounds(w).find(r=>r.id===ui(w).roundId)||rounds(w).at(-1);}
function diffPanel(w){const r=selectedRound(w);if(!r)return '<div class="cm-inspector-pad"><h3>成果从这里逐步形成</h3><p>启动 AI 轮次后，在这里逐项查看建议与原文的差异。</p></div>';const patches=r.patches||[],a=asset(w),stale=a?(r.appliedAssetKey||r.assetKey)!==C.key(a):(r.appliedTaskRevision||r.taskRevision)!==task(w)?.revision;return `<div class="cm-inspector-pad"><div class="cm-between"><b>${esc(r.id)} · ${esc(r.state)}</b><span class="cm-muted">${patches.filter(p=>p.state==='待审查').length} 处待审查</span></div>${stale&&patches.some(p=>p.state==='待审查')?'<p class="cm-warning">关联版本已变化，请重新启动一轮。旧建议保留供对照。</p>':''}${patches.map(p=>`<section class="cm-diff"><div class="cm-between"><h3>${esc(p.title)}</h3><span class="cm-decision">${esc(p.state)}</span></div><p class="cm-muted">${esc(p.why)}</p><div class="cm-before"><small>原文</small><div>${text(p.before)||'尚未填写'}</div></div><div class="cm-after"><small>建议改为</small><div>${text(p.after)}</div></div>${p.state==='待审查'&&!stale&&w.status!=='已关闭'?`<div class="cm-diff-actions">${b('保留原文','reject',r.id+'|'+p.id,'sm')}${b('采纳此项','accept',r.id+'|'+p.id,'primary sm')}</div>`:`<p class="cm-muted">${p.state==='已采纳'?'已写入 '+esc(p.savedKey||'任务修订')+'；验证与审批需按新内容重新完成。':p.state==='保留原文'?'原文未修改，建议保留供追溯。':'当前建议只读。'}</p>`}</section>`).join('')||'<p class="cm-muted">本轮尚无可审查的差异。</p>'}</div>`;}
function sourcePanel(w){const a=asset(w),t=task(w);return `<div class="cm-inspector-pad"><h3>本次协作使用的内容</h3><dl class="cm-context"><dt>关联对象</dt><dd>${esc(a?a.name:t?.name||'尚未关联')}</dd><dt>精确版本</dt><dd>${esc(a?C.key(a):t?.id+' · 修订 '+t?.revision)}</dd><dt>来源说明</dt><dd>${text(a?.source||t?.goal||'尚未填写')}</dd></dl><div class="cm-note">建议仅使用本事项的关联内容与明确加入的指令。独立留出集、盲评个人答案不会显示在这里。</div>${a?vb('查看完整内容与引用','asset',C.key(a)):(w.plazaTaskId?'<button class="btn" data-pz="open-task" data-key="'+esc(w.plazaTaskId)+'">打开任务</button>':vb('打开任务','task',w.taskId))}</div>`;}
function historyPanel(w){return `<div class="cm-inspector-pad"><h3>每一处决定都有记录</h3>${rounds(w).slice().reverse().map(r=>`<div class="cm-history"><b>${esc(r.id)} · ${esc(r.state)}</b><p class="cm-muted">${tm(r.finishedAt||r.startedAt)}</p>${(r.patches||[]).map(p=>'<p>'+esc(p.title)+' · <b>'+esc(p.state)+'</b>'+(p.savedKey?' · '+esc(p.savedKey):'')+'</p>').join('')}${b('查看这一轮','round-view',r.id,'ghost sm')}</div>`).join('')||'<p>尚无 AI 轮次记录。</p>'}</div>`;}
function handoff(w){const a=asset(w);if(!a)return `<div class="cm-handoff"><span class="cm-kicker">接着做什么</span><h3>回到任务确认方案</h3><p>采纳的内容写入任务修订，后续仍在任务内完成依赖、试评与冻结。</p>${(w.plazaTaskId?'<button class="btn" data-pz="open-task" data-key="'+esc(w.plazaTaskId)+'">打开关联任务</button>':vb('打开关联任务','task',w.taskId))}</div>`;const status=a.status;return `<div class="cm-handoff"><div class="cm-between"><span class="cm-kicker">接着做什么</span>${stateBadge(status)}</div><h3>${status==='待准入'?'等待 '+esc(a.governance.assigneeName||roleNames[a.governance.assignee]):status==='已发布'?'成果已发布，可以复用':'先把成果完善到可验证'}</h3><p>${status==='待准入'?'打开本次内容、变更与验证证据，即可在这里继续处理。':status==='已发布'?'当前版本已固定。继续修改会形成新修订，保留本次审批记录。':'编辑实际内容，再检查引用与验证证据；保存草稿不等于通过审核。'}</p><div class="v2-actions">${status==='待准入'?vb(EvalUI.core.ordinary(a)?'查看双人确认':a.expertConfirmed?'查看并独立审核':'查看并专家确认','approve',C.key(a),'primary'):b(status==='已发布'?'继续完善新修订':'编辑成果','edit',w.id,'primary')}${vb('内容与验证','asset',C.key(a))}</div>${status==='待准入'?`<div class="cm-handoff-tools">${vb('催办','remind',w.id,'ghost sm')}${vb('改派','reassign',w.id,'ghost sm')}${b('查看交接内容','handoff',w.id,'ghost sm')}</div>`:''}</div>`;}
pages.work=()=>{const w=work();if(!w)return pages.collab();const a=asset(w),s=ui(w);return `<div class="cm-back">${b('← 所有协作','back','','ghost sm')}</div>`+head(esc(w.title),w.id+' · '+w.status,b(w.status==='已关闭'?'重新打开':'关闭事项','close-work',w.id))+`<div class="cm-contextbar"><div><span class="cm-kicker">共同完善</span> ${a?b(esc(a.name)+' · '+esc(a.version),'asset',w.id,'ghost'):(w.plazaTaskId?'<button class="btn ghost" data-pz="open-task" data-key="'+esc(w.plazaTaskId)+'">'+esc(task(w)?.name||'关联任务')+'</button>':vb(esc(task(w)?.name||'关联任务'),'task',w.taskId,'ghost'))}</div>${members()}</div><div class="cm-workspace"><section class="cm-conversation"><div class="cm-panel-head"><h2>讨论与协作</h2><span>讨论 → 指令 → 可审查的建议</span></div><div class="cm-thread">${conversation(w)}</div>${composer(w)}</section><aside class="cm-inspector"><section class="cm-artifact"><div class="cm-panel-head"><div><span class="cm-kicker">一起完善的成果</span><h2>${esc(a?.name||'评测方案')}</h2></div>${a?stateBadge(a.status):''}</div><div class="cm-tabs" role="tablist" aria-label="成果视图">${[['diff','产物与差异'],['source','来源与隔离'],['history','版本与决定']].map(([key,label])=>`<button role="tab" aria-selected="${s.tab===key}" data-cm="tab" data-key="${key}">${label}</button>`).join('')}</div>${s.tab==='source'?sourcePanel(w):s.tab==='history'?historyPanel(w):diffPanel(w)}</section>${handoff(w)}</aside></div>`;};
pages.overview=()=>head('工作概览','继续正在推进的评测，或从一个新目标开始。',vb('新建评测任务','new','','primary'))+`<div class="cm-overview-grid"><section class="card"><div class="cardhead"><h2>最近的评测任务</h2>${vb('全部任务','tasks','','ghost sm')}</div>${table(['任务','对象',''],S.evalTasks.slice(-5).reverse().map(t=>[esc(t.name),esc(t.object||'待补充'),vb('继续任务','task',t.id,'sm')]))}</section><section class="card"><div class="cardhead"><h2>继续协作</h2>${b('全部协作','back','','ghost sm')}</div><div class="cm-overview-works">${db().works.filter(w=>w.status==='进行中').slice(0,2).map(workCard).join('')}</div></section></div><div class="grid2 mt">${section('快速开始',`<div class="pad stack">${['rag','office','pet'].map(k=>vb('复用 '+templates.find(t=>t.id===k).name,'template',k)).join('')}</div>`)}${section('独立建设资产',`<div class="pad"><p>维护数据、用例与评分能力，让下一次评测直接复用。</p>${vb('进入资产中心','assets')}</div>`)}</div><div class="mt">${section('最近运行',table(['运行','执行状态','质量结论',''],S.runs.slice(0,4).map(r=>[esc(r.name),stateBadge(r.state),stateBadge(r.verdict),vb('查看运行','run-open',r.id,'sm')])))}</div>`;
function newWork(mode='asset'){modal('发起协作',`<div class="stack">${field('协作事项名称','<input class="input" id="cm-title" placeholder="例如：完善拒绝服务的判定规则">')}${field('围绕哪个任务或资产',`<select class="input" id="cm-ref">${mode==='task'?taskOptions()+assetOptions():assetOptions()+taskOptions()}</select>`)}<p class="muted">关联精确版本；讨论、建议和交接保存在同一个事项中。</p></div>`,vb('取消','close')+b('开始协作','create-work','','primary'));}
function assetOptions(){return '<optgroup label="资产">'+core().list().filter(a=>a.status!=='停用').map(a=>`<option value="asset|${esc(C.key(a))}">${esc(a.name+' · '+a.version)}</option>`).join('')+'</optgroup>';}
function taskOptions(){return '<optgroup label="任务">'+S.evalTasks.map(t=>`<option value="task|${esc(t.id)}">${esc(t.name)}</option>`).join('')+'</optgroup>';}
function start(w){if(!guard('engineer'))return;const a=asset(w),t=task(w),r=M.start(db(),w,{id:core().id('AI'),assetKey:a&&C.key(a),taskRevision:t?.revision,at:now()});const snapshot=a?C.clone(a):null,taskSnapshot=t?C.clone(t):null;ui(w).roundId=r.id;ui(w).tab='diff';show();const tick=()=>{if(r.state!=='运行中')return;r.stage++;if(r.stage>=3){r.patches=M.suggest(snapshot,taskSnapshot,r.instructions);r.state='已完成';r.finishedAt=now();}UI.commit();if(S.route==='work'&&work()?.id===w.id)show();if(r.state==='运行中')setTimeout(tick,1100);};setTimeout(tick,1100);}
function accept(w,r,p){if(!guard('engineer'))return;if(w.status==='已关闭')throw Error('事项已关闭，请重新打开后继续。');const a=asset(w),t=task(w);if(a){if((r.appliedAssetKey||r.assetKey)!==C.key(a))throw Error('关联版本已经变化，请重新生成建议。');const patch=M.apply(a,p),n=core().revise(a,patch);if(n.caseSpec?.prd){n.caseSpec.prd.version=n.version;n.caseSpec=CaseContracts.legacySpec(n.caseSpec.prd,CaseContracts.catalog(S));n.content=CaseAuthoring.content(n.caseSpec);}else if(n.assetSpec)n.content=Object.values(n.assetSpec.fields).join('\n');w.assetKey=C.key(n);r.appliedAssetKey=w.assetKey;p.savedKey=w.assetKey;UI.checks(n);}else{if(!t||t.manifest||t.run)throw Error('任务已冻结或不可用，请在任务工作区建立新修订。');if((r.appliedTaskRevision||r.taskRevision)!==t.revision)throw Error('任务已变化，请重新生成建议。');const patch=M.apply(t,p);t[p.path[0]]=patch[p.path[0]];t.revision++;t.pilot=null;t.confirmedRevision=0;r.appliedTaskRevision=t.revision;p.savedKey=t.id+' · 修订 '+t.revision;if(w.plazaTaskId){PlazaCore.invalidate(t);PlazaReview.persist();}}
 p.state='已采纳';p.decidedAt=now();p.actor=roleNames[S.role];show();toast('已保存这处修改；新修订需重新检查与审核。','success');}
let editingCapability=null;
function capabilityForm(a=null){if(!guard('engineer'))return;editingCapability=a;const c=PRDContracts,modern=a?.config?.contractVersion===2;modal(a?'核对能力登记':'登记能力草稿',`<div class="stack">${field('能力名称',`<input class="input" id="cap-name" value="${esc(a?.name||'')}" placeholder="例如：通用事实评分器">`)}${field('能力类型',`<select class="input" id="cap-kind" ${a?'disabled':''}><option value="">请选择能力职责</option>${Object.entries(c.kinds).map(([k,n])=>`<option value="${k}" ${a?.kind===k?'selected':''}>${n}</option>`).join('')}</select>`)}${a&&!modern?'<div class="notice warn">此记录来自旧版混合分类。请根据真实用途重新确认适用对象、任务类型和协议；系统不推定原选择的意图。</div>':''}<fieldset class="prd-choice"><legend>适用对象类型（可多选）</legend>${c.objects.map(x=>`<label class="checkline"><input type="checkbox" name="cap-target" value="${x}" ${modern&&a.targets?.includes(x)?'checked':''}>${x}</label>`).join('')}</fieldset>${field('任务类型版本引用（每行 key@版本）',`<textarea id="cap-task-types" class="input" rows="3" placeholder="从任务类型目录复制精确版本引用">${esc(modern?(a.config.taskTypeRefs||[]).join('\n'):'')}</textarea>`,'任务类型独立登记；业务案例名不能充当稳定 key。允许先留空保存草稿。')}<fieldset class="prd-choice"><legend>支持协议（可多选）</legend>${Object.entries(c.protocols).map(([k,n])=>`<label class="checkline"><input type="checkbox" name="cap-protocol" value="${k}" ${modern&&a.config.protocols?.includes(k)?'checked':''}>${n}</label>`).join('')}</fieldset><div class="cm-note">登记草稿不代表能力就绪。类型引用、输入输出契约、协议和专项资格仍须验证；当前交互稿未连接真实目录服务。</div></div>`,vb('取消','close')+b('保存能力草稿','save-capability','','primary'),true);}
const priorCapabilities=pages.capabilities;
pages.capabilities=()=>{const list=core().list().filter(a=>a.config?.capabilityRegistration);const base=priorCapabilities().replace(`<div class="grid3 mb">${stat('已就绪主执行器','3','按对象类型选择一个主执行器','play')}${stat('独立评分实现','4','每项指标指定一种正式评分方法','shield')}${stat('待验证能力','2','端侧适配 / LLM 裁判资格','clock')}</div>`,'');return base+section('我登记的能力',list.length?table(['能力名称','适用范围','版本 / 状态',''],list.map(a=>[esc(a.name),esc(a.config.contractVersion===2?((a.targets||[]).join(' / ')||'对象待补充')+' · '+((a.config.taskTypeRefs||[]).join('、')||'任务类型待绑定'):'旧版分类待核对：'+(a.config.supportedTask||'未填写')),esc(a.version)+' · '+stateBadge(a.status),b('核对登记','edit-capability',C.key(a),'sm')+vb('继续配置','edit-asset',C.key(a),'sm')+b('发起协作','cap-work',C.key(a),'sm')+vb('查看内容','asset',C.key(a),'sm')])):'<div class="pad muted">还没有登记记录。点击“登记能力”保存第一条草稿。</div>');};
function saveCapability(){if(!guard('engineer'))return;const selected=name=>Array.from(document.querySelectorAll('input[name="'+name+'"]:checked')).map(e=>e.value);const data=PRDContracts.capability({name:document.getElementById('cap-name').value,kind:document.getElementById('cap-kind').value,targets:selected('cap-target'),protocols:selected('cap-protocol'),taskTypeRefs:document.getElementById('cap-task-types').value.split(/\n/).map(s=>s.trim()).filter(Boolean)});const a=editingCapability?core().edit(editingCapability,{...data,config:{...editingCapability.config,...data.config}}):core().adopt({id:core().id('CAP'),version:'r1',...data,source:'能力登记',owner:roleNames[S.role],assetSpec:{fields:{}}});editingCapability=null;UI.commit();UI.forceClose();go('capabilities');toast('能力草稿已保存；尚未通过匹配与资格验证。','success');}
function capWork(a){let w=db().works.find(w=>w.assetKey===C.key(a)&&w.status==='进行中');if(!w){w={id:core().id('CW'),title:a.name+' · 契约与资格准备',status:'进行中',assetKey:C.key(a),messages:[]};db().works.push(w);}open(w);}
function savedFromEditor(a){const id=S.v2.collabEditReturn,w=db().works.find(w=>w.id===id);if(w&&asset(w)?.id===a.id){w.assetKey=C.key(a);UI.commit();}}
UI.assetSaved=savedFromEditor;const persist=UI.persistCase;UI.persistCase=data=>{const a=persist(data);savedFromEditor(a);return a;};
async function handle(act,key){const w=work();switch(act){
 case'edit-capability':capabilityForm(core().find(key));break;
 case'open':open(db().works.find(w=>w.id===key));break;case'back':go('collab');break;
 case'new-work':newWork(key);break;case'create-work':{const title=document.getElementById('cm-title').value.trim(),[kind,ref]=document.getElementById('cm-ref').value.split('|');if(!title)throw Error('请填写协作事项名称，说明要一起解决的问题。');if(!ref)throw Error('请先选择关联任务或资产。');const x={id:core().id('CW'),title,status:'进行中',messages:[],[kind==='asset'?'assetKey':'taskId']:ref};db().works.push(x);UI.commit();UI.forceClose();open(x);break;}
 case'mode':ui(w).mode=key;show();document.getElementById('cm-draft')?.focus();break;case'tab':ui(w).tab=key;show();break;
 case'send':{if(w.status==='已关闭')throw Error('事项已关闭，请先重新打开。');const value=(ui(w).draft||'').trim();if(!value){document.getElementById('cm-draft').focus();return;}if(ui(w).mode==='instruction')db().instructions.push({id:core().id('INS'),workId:w.id,state:'待执行',text:value,at:now()});else addMessage(w,value);ui(w).draft='';show();document.getElementById('cm-draft').focus();break;}
 case'withdraw':{const i=db().instructions.find(x=>x.id===key);if(i?.state!=='待执行')throw Error('指令已被读取，无法撤回；可以停止当前轮次。');i.state='已撤回';show();break;}
 case'start':start(w);break;case'stop':{const r=db().rounds.find(r=>r.id===key);M.stop(db(),r);r.finishedAt=now();show();break;}
 case'round-view':ui(w).roundId=key;ui(w).tab='diff';show();document.querySelector('.cm-artifact')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case'accept':case'reject':{const [rid,pid]=key.split('|'),r=db().rounds.find(x=>x.id===rid),p=r?.patches.find(x=>x.id===pid);if(!p||p.state!=='待审查')throw Error('这处建议已经处理。');if(act==='accept')accept(w,r,p);else{p.state='保留原文';p.decidedAt=now();p.actor=roleNames[S.role];show();}break;}
 case'asset':UI.assetDetail(asset(w));break;
 case'edit':{if(!guard('engineer'))return;S.v2.collabEditReturn=w.id;UI.editAsset(asset(w),null);if(S.v2.activeAsset)w.assetKey=S.v2.activeAsset;UI.commit();break;}
 case'save-return':if(CaseWorkbench.saveForTask()){const x=db().works.find(x=>x.id===S.v2.collabEditReturn);S.v2.collabEditReturn=null;UI.forceClose();open(x);toast('成果草稿已保存，已返回原协作事项。','success');}break;
 case'close-work':if(running(w))throw Error('AI 轮次仍在进行，请先停止或等待完成。');w.status=w.status==='已关闭'?'进行中':'已关闭';show();break;
 case'handoff':{const a=asset(w);modal('本次交接',`<h3>${esc(a.name+' · '+a.version)}</h3><p>当前处理人：${esc(a.governance.assigneeName||roleNames[a.governance.assignee])}</p><p>确认范围：本次内容、版本变更与四层验证证据。</p>`,vb('查看并处理','approve',C.key(a),'primary')+vb('关闭','close'),false,true);break;}
 case'save-capability':saveCapability();break;case'cap-work':capWork(core().find(key));break;
 }}
document.addEventListener('click',e=>{const el=e.target.closest('[data-cm]');if(el){e.preventDefault();e.stopImmediatePropagation();Promise.resolve(handle(el.dataset.cm,el.dataset.key||'')).catch(error=>toast(error.message,'error'));return;}const old=e.target.closest('[data-action]');if(old?.dataset.action==='cap-register'||old?.dataset.action==='cap-save'){e.preventDefault();e.stopImmediatePropagation();try{old.dataset.action==='cap-register'?capabilityForm():saveCapability();}catch(error){toast(error.message,'error');}}},true);
document.addEventListener('input',e=>{if(e.target.id==='cm-draft'){ui(work()).draft=e.target.value;UI.commit();}});
document.addEventListener('keydown',e=>{if(e.target.id==='cm-draft'&&(e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();handle('send').catch(error=>toast(error.message,'error'));}});
// The inbox remains a global utility. Task and collaboration pages own the work.
for(const g of navGroups)g.items=g.items.filter(([id])=>id!=='inbox');
const renderBefore=render;render=function(){renderBefore();const inbox=document.querySelector('.topbar [data-action="inbox"]');if(inbox){const count=UI.getTodos().length;inbox.querySelector('.cm-inbox-count')?.remove();inbox.setAttribute('aria-label','我的待办'+(count?'，'+count+'项':''));if(count)inbox.insertAdjacentHTML('beforeend','<span class="cm-inbox-count">'+count+'</span>');}if(S.route==='case-builder'&&S.v2.collabEditReturn){const w=db().works.find(x=>x.id===S.v2.collabEditReturn);if(w&&!document.querySelector('.cm-save-return'))document.querySelector('#main').insertAdjacentHTML('afterbegin',`<div class="cm-save-return"><span>正在完善：${esc(w.title)}</span>${b('保存并返回协作','save-return','','primary sm')}</div>`);}};
migrate();if(S.route==='case-builder'&&S.v2.collabEditReturn){const w=db().works.find(x=>x.id===S.v2.collabEditReturn),a=w&&asset(w);if(a?.kind==='case'&&S.v2.activeAsset===C.key(a))CaseWorkbench.open({asset:a});else S.v2.collabEditReturn=null;}render();
})();
